	@Test
	void omittedFunctionArgumentCannotReadAnOrdinaryJoinSibling() {
		Value needle = VF.createLiteral("needle");
		FunctionCall call = new OmittedArgumentsCall(FN.CONTAINS.stringValue(), Var.of("hidden"),
				new ValueConstant(needle));
		TupleExpr right = new Extension(new SingletonSet(), new ExtensionElem(call, "flag"));
		Join join = new Join(values(row("hidden", needle)), right);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT);

		assertThat(evaluate(strategy.precompile(join), EmptyBindingSet.getInstance()))
				.containsExactly(row("hidden", needle));
	}

