	@Test
	void omittedVolatileFunctionArgumentKeepsIndependentReplay() {
		FunctionCall call = new OmittedArgumentsCall(FN.CONCAT.stringValue(), new FunctionCall("STRUUID"));
		TupleExpr right = new Extension(new SingletonSet(), new ExtensionElem(call, "fresh"));
		Join join = new Join(values(row("id", VF.createLiteral("first")), row("id", VF.createLiteral("second"))),
				right);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT);

		List<BindingSet> results = evaluate(strategy.precompile(join), EmptyBindingSet.getInstance());
		assertThat(results).hasSize(2);
		assertThat(results).extracting(row -> row.getValue("id"))
				.containsExactlyInAnyOrder(VF.createLiteral("first"), VF.createLiteral("second"));
		assertThat(results.get(0).getValue("fresh")).isNotNull().isEqualTo(results.get(1).getValue("fresh"));
	}

