	@ParameterizedTest(name = "optional={0}")
	@ValueSource(booleans = { false, true })
	void graphSelectorUsesItsActualOwnerWithoutChangingBodyInput(boolean optional) {
		IRI present = VF.createIRI("urn:frame:present-graph");
		IRI missing = VF.createIRI("urn:frame:missing-graph");
		Value hit = VF.createLiteral(true);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(graphSource(present), null);
		TupleExpr left = values(row("id", VF.createLiteral("present"), "g", present),
				row("id", VF.createLiteral("present"), "g", present),
				row("id", VF.createLiteral("missing"), "g", missing),
				row("id", VF.createLiteral("rdf4j-nil"), "g", RDF4J.NIL),
				row("id", VF.createLiteral("sesame-nil"), "g", SESAME.NIL));
		Graph graph = selectorOnlyGraph();
		TupleExpr host = optional ? new LeftJoin(left, graph) : new Join(left, graph);
		QueryEvaluationStep step = strategy.precompile(host, context);
		List<BindingSet> rows = evaluate(step, EmptyBindingSet.getInstance());
		List<BindingSet> expected = new ArrayList<>(List.of(
				row("id", VF.createLiteral("present"), "g", present, "hit", hit),
				row("id", VF.createLiteral("present"), "g", present, "hit", hit)));
		if (optional) {
			expected.add(row("id", VF.createLiteral("missing"), "g", missing));
			expected.add(row("id", VF.createLiteral("rdf4j-nil"), "g", RDF4J.NIL));
			expected.add(row("id", VF.createLiteral("sesame-nil"), "g", SESAME.NIL));
		}
		String algorithm = optional ? ((LeftJoin) host).getAlgorithmName() : ((Join) host).getAlgorithmName();
		assertAll(
				() -> assertThat(rows).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(algorithm).isEqualTo("ScopedCorrelatedJoinIterator"));

		BindingSet unrelated = BindingFrameBindings.push(new BindingFrameBindings.Scope(), row(), row("g", missing),
				context);
		assertThat(evaluate(step, unrelated)).as("the real owner wins over an unrelated probe")
				.containsExactlyInAnyOrderElementsOf(expected);
		Graph independent = selectorOnlyGraph();
		assertThat(evaluate(strategy.precompile(independent, context), unrelated))
				.as("an unowned probe cannot select the graph")
				.containsExactly(row("g", present, "hit", hit));
	}

	private static Graph selectorOnlyGraph() {
		Filter body = new Filter(new SingletonSet(), new Not(new Bound(Var.of("g"))));
		return new Graph(Var.of("g"),
				new Extension(body, new ExtensionElem(new ValueConstant(VF.createLiteral(true)), "hit")));
	}

	@Test
	void graphOwnerGrantStopsAtInvocationAndProbeBarriers() {
		IRI present = VF.createIRI("urn:frame:present-graph");
		IRI missing = VF.createIRI("urn:frame:missing-graph");
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(graphSource(present), null);
		Graph graph = selectorOnlyGraph();
		Join owner = new Join(values(row("g", missing)), graph);
		QueryEvaluationStep step = strategy.precompile(graph, context);
		BindingSet owned = BindingFrameBindings.push(BindingFrameBindings.scopeFor(owner), row(), row("g", missing),
				context);
		BindingSet wrongOwner = BindingFrameBindings.push(new BindingFrameBindings.Scope(), row(), row("g", missing),
				context);
		BindingSet isolated = BindingFrameBindings.isolate(owned, context);
		BindingSet empty = BindingFrameBindings.withSubstitutionDomain(owned, Set.of(), context);
		BindingSet unbound = BindingFrameBindings.withLateralDomain(owned, Set.of("g"), Set.of("g"), context);
		BindingSet expected = row("g", present, "hit", VF.createLiteral(true));
		assertAll(
				() -> assertThat(evaluate(step, owned)).as("the actual owner selects its missing graph").isEmpty(),
				() -> assertThat(evaluate(step, wrongOwner)).as("a different owner").containsExactly(expected),
				() -> assertThat(evaluate(step, isolated)).as("a probe isolation boundary").containsExactly(expected),
				() -> assertThat(evaluate(step, empty)).as("a newer empty invocation").containsExactly(expected),
				() -> assertThat(evaluate(step, unbound)).as("a newer declared but unbound input")
						.containsExactly(expected));
	}

