	@Test
	void liftedExistsGraphUsesTheActualFilterOwner() {
		IRI present = VF.createIRI("urn:frame:present-graph");
		IRI missing = VF.createIRI("urn:frame:missing-graph");
		Value hit = VF.createLiteral(true);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(graphSource(present), null);
		TupleExpr left = values(row("id", VF.createLiteral("present"), "g", present),
				row("id", VF.createLiteral("present"), "g", present),
				row("id", VF.createLiteral("missing"), "g", missing));
		Extension local = new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(hit), "hit"));
		Filter gate = new Filter(local, new Exists(new Graph(Var.of("g"), new SingletonSet())));
		gate.setConditionBindingScope(ConditionBindingScope.ALL);
		Join owner = new Join(left, gate);
		QueryEvaluationStep step = strategy.precompile(owner, context);
		List<BindingSet> expected = List.of(
				row("id", VF.createLiteral("present"), "g", present, "hit", hit),
				row("id", VF.createLiteral("present"), "g", present, "hit", hit));
		BindingSet unrelated = BindingFrameBindings.push(new BindingFrameBindings.Scope(), row(), row("g", missing),
				context);
		assertAll(
				() -> assertThat(evaluate(step, row())).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(evaluate(step, unrelated)).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(owner.getAlgorithmName()).isEqualTo("ScopedCorrelatedJoinIterator"));
	}

