	@Test
	void existsGraphValuesUsesTheRetainedWithheldEntry() {
		IRI graphName = VF.createIRI("urn:frame:graph");
		Value different = VF.createLiteral("different");
		TripleSource graphSource = new TripleSource() {
			@Override
			public CloseableIteration<? extends Resource> getContextIDs() {
				return new SingletonIteration<>(graphName);
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new EmptyIteration<>();
			}
		};
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet logical = row("input", OUTER);
		BindingSet withheld = BindingFrameBindings.without(logical, Set.of("input"), context);
		BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(), withheld,
				row("input", different), context);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(graphSource, null);
		Exists mismatch = new Exists(new Graph(Var.of("graph", graphName, false, true),
				values(row("input", different))));
		Exists match = new Exists(new Graph(Var.of("graph", graphName, false, true),
				values(row("input", OUTER))));

		assertThat(strategy.precompile(mismatch, context).evaluate(logical)).isEqualTo(VF.createLiteral(false));
		assertThat(strategy.precompile(mismatch, context).evaluate(framed)).isEqualTo(VF.createLiteral(false));
		assertThat(strategy.precompile(match, context).evaluate(framed)).isEqualTo(VF.createLiteral(true));
	}

	@Test
	void existsDomainProofIncludesGraphInputsHiddenByProjectionAndNestedExists() {
		IRI graph = VF.createIRI("urn:frame:graph");
		Projection projected = new Projection(values(row("x", OTHER)), new ProjectionElemList(), true);
		TupleExpr nested = new Filter(new SingletonSet(), new Not(new Not(new Exists(values(row("x", OTHER))))));
		Graph projectedGraph = new Graph(Var.of("g", graph, false, true), projected);
		Graph nestedGraph = new Graph(Var.of("g", graph, false, true), nested);
		Graph fixedGraph = new Graph(Var.of("g", graph, false, true), new SingletonSet());
		TupleExpr nestedOutsideGraph = new Filter(new SingletonSet(), new Exists(values(row("x", OTHER))));
		assertSoftly(soft -> {
			soft.assertThat(QueryEvaluationUtility.existsSubstitutionInputs(projectedGraph).bindingNames())
					.as("GRAPH entry into projected VALUES")
					.contains("x");
			soft.assertThat(QueryEvaluationUtility.existsSubstitutionInputs(nestedGraph).bindingNames())
					.as("GRAPH entry into nested EXISTS VALUES")
					.contains("x");
			soft.assertThat(QueryEvaluationUtility.existsSubstitutionInputs(fixedGraph).needsDynamicDomain())
					.as("fixed GRAPH with no entry reads")
					.isFalse();
			soft.assertThat(QueryEvaluationUtility.existsSubstitutionInputs(nestedOutsideGraph).needsDynamicDomain())
					.as("nested EXISTS owns its own invocation domain")
					.isFalse();
		});
	}

