	@Test
	void existsSubstitutionKeepsLocalOptionalWritesAndErrors() {
		Value entry = VF.createLiteral("entry");
		Value written = VF.createLiteral("written");
		Value right = VF.createLiteral("right");
		QueryEvaluationContext context = new BindingSubstitutionQueryEvaluationContext(
				new QueryEvaluationContext.Minimal((Dataset) null), Set.of("x"));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		for (boolean error : List.of(false, true)) {
			ValueExpr assignment = error
					? new MathExpr(new ValueConstant(OUTER), new ValueConstant(VF.createLiteral(1)),
							MathExpr.MathOp.PLUS)
					: new ValueConstant(written);
			Union left = new Union(new Extension(new SingletonSet(), new ExtensionElem(assignment, "x")),
					new SingletonSet());
			LeftJoin optional = new LeftJoin(left, values(row("x", right)));
			List<BindingSet> result = new ArrayList<>();
			try (CloseableIteration<BindingSet> rows = strategy.precompile(optional, context)
					.evaluate(row("x", entry))) {
				while (rows.hasNext()) {
					result.add(rows.next());
				}
			}
			assertThat(result).as("local assignment error=%s", error)
					.containsExactlyInAnyOrder(row("x", error ? right : written), row("x", entry));
		}
	}

	@Test
	void filterConditionWhitelistLimitsWithheldExistsInputs() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet entry = BindingFrameBindings.without(row("allowed", OUTER, "hidden", OTHER),
				Set.of("allowed", "hidden"), context);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null) {
			@Override
			protected QueryEvaluationStep precompileTupleExpr(TupleExpr expression,
					QueryEvaluationContext inputContext) {
				if (expression instanceof OpaqueOperator) {
					return bindings -> bindings.getValue("hidden") == null ? new EmptyIteration<>()
							: new SingletonIteration<>(bindings);
				}
				return super.precompileTupleExpr(expression, inputContext);
			}
		};

		assertSoftly(soft -> {
			soft.assertThat(evaluateFilterCondition(strategy, context, entry,
					new Exists(new Filter(new SingletonSet(), new Bound(Var.of("hidden")))))).isEmpty();
			soft.assertThat(evaluateFilterCondition(strategy, context, entry,
					new Exists(new Filter(new SingletonSet(), new Bound(Var.of("allowed")))))).containsExactly(row());
			soft.assertThat(evaluateFilterCondition(strategy, context, entry,
					new Exists(values(row("allowed", OTHER))))).isEmpty();
			soft.assertThat(evaluateFilterCondition(strategy, context, entry,
					new Exists(values(row("allowed", OUTER))))).containsExactly(row());
			soft.assertThat(evaluateFilterCondition(strategy, context, entry, new Exists(new OpaqueOperator())))
					.isEmpty();
		});
	}

