	private static List<BindingSet> evaluateFilterCondition(DefaultEvaluationStrategy strategy,
			QueryEvaluationContext context, BindingSet entry, ValueExpr condition) {
		Filter filter = new Filter(new SingletonSet(), condition);
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("allowed")));
		List<BindingSet> result = new ArrayList<>();
		try (CloseableIteration<BindingSet> rows = strategy.precompile(filter, context).evaluate(entry)) {
			while (rows.hasNext()) {
				result.add(rows.next());
			}
		}
		return result;
	}

