	void lateralRuntimeNestedOwnersPreferNearestAndFallBackForUndef(boolean optional) {
		Value outer = VF.createLiteral("outer-owner");
		Value inner = VF.createLiteral("inner-owner");
		BindingSetAssignment near = values(row("x", inner), row());
		Extension right = new Extension(new SingletonSet(), new ExtensionElem(Var.of("x"), "witness"));
		Lateral lateral = new Lateral(new SingletonSet(), right, Set.of("x"));
		TupleExpr innerHost = optional ? new LeftJoin(near, lateral) : new Join(near, lateral);
		TupleExpr outerHost = optional ? new LeftJoin(values(row("x", outer)), innerHost)
				: new Join(values(row("x", outer)), innerHost);
		List<Value> seen = new ArrayList<>();
		DefaultEvaluationStrategy strategy = lateralInputObserver(seen);
		List<BindingSet> result = evaluate(strategy.precompile(new QueryRoot(outerHost)), row());

		assertAll(
				() -> assertThat(seen).as("nearest owner, then outer fallback").containsExactly(inner, outer),
				() -> assertThat(result).containsExactly(row("x", outer, "witness", outer)));
	}

	private static DefaultEvaluationStrategy lateralInputObserver(List<Value> seen) {
		return new DefaultEvaluationStrategy(source(), null) {
			@Override
			public QueryValueEvaluationStep precompile(ValueExpr expression, QueryEvaluationContext context) {
				QueryValueEvaluationStep prepared = super.precompile(expression, context);
				if (expression instanceof Var variable && "x".equals(variable.getName())
						&& expression.getParentNode() instanceof ExtensionElem element
						&& "witness".equals(element.getName())) {
					return bindings -> {
						Value value = prepared.evaluate(bindings);
						seen.add(value);
						return value;
					};
				}
				return prepared;
			}
		};
	}

