		BindingSet left = bound ? row("x", OUTER) : row();
		TupleExpr local = new Extension(values(row("x", OTHER)), new ExtensionElem(Var.of("x"), "local"));
		ProjectionElemList elements = projected
				? new ProjectionElemList(new ProjectionElem("x", "renamed"), new ProjectionElem("local"))
				: new ProjectionElemList(new ProjectionElem("local"));
