	@Test
	void lateralPreparedOnceRetainsOneShotValuesAndVolatileOccurrences() {
		AtomicInteger traversals = new AtomicInteger();
		BindingSetAssignment oneShot = new BindingSetAssignment();
		oneShot.setDeclaredBindingNames(Set.of("v"));
		oneShot.setBindingSets(() -> {
			assertThat(traversals.incrementAndGet()).isEqualTo(1);
			return List.<BindingSet>of(row("v", OTHER)).iterator();
		});
		Projection projection = new Projection(oneShot, new ProjectionElemList(new ProjectionElem("v")), true);
		TupleExpr right = new Extension(new Join(projection, new SingletonSet()),
				new ExtensionElem(new FunctionCall("STRUUID"), "fresh"));
		Lateral lateral = new Lateral(values(row("x", OUTER), row("x", OUTER)), right, Set.of("x", "y"));
		QueryEvaluationStep prepared = new DefaultEvaluationStrategy(source(), null).precompile(lateral);
		for (int run = 0; run < 2; run++) {
			boolean withApiY = run == 1;
			List<BindingSet> actual = evaluate(prepared, withApiY ? row("y", OTHER) : row());
			assertThat(actual).hasSize(2);
			assertThat(actual).allSatisfy(result -> {
				assertThat(result.getValue("x")).isEqualTo(OUTER);
				assertThat(result.getValue("v")).isEqualTo(OTHER);
				assertThat(result.getValue("y")).isEqualTo(withApiY ? OTHER : null);
				assertThat(result.getValue("fresh")).isNotNull();
			});
			assertThat(actual.get(0).getValue("fresh")).isNotEqualTo(actual.get(1).getValue("fresh"));
		}
		assertThat(traversals).hasValue(1);
	}

	@Test
	void lateralPreparedRightRetainsPinnedFunctionAcrossInputDomains() {
		String uri = "urn:frame:pinned-lateral-function";
		Function original = constantFunction(uri, OUTER);
		Function replacement = constantFunction(uri, OTHER);
		FunctionRegistry registry = FunctionRegistry.getInstance();
		registry.add(original);
		try {
			FunctionCall pinned = QueryEvaluationUtility.pinFunctions(new FunctionCall(uri));
			Projection projection = new Projection(new SingletonSet(), new ProjectionElemList(), true);
			TupleExpr right = new Extension(new Join(projection, new SingletonSet()),
					new ExtensionElem(pinned, "result"));
			Lateral lateral = new Lateral(new SingletonSet(), right, Set.of("x", "y"));
			QueryEvaluationStep prepared = new DefaultEvaluationStrategy(source(), null).precompile(lateral);
			registry.remove(original);
			registry.add(replacement);
			assertThat(evaluate(prepared, row())).containsExactly(row("result", OUTER));
			assertThat(evaluate(prepared, row("x", OTHER))).containsExactly(row("x", OTHER, "result", OUTER));
			assertThat(evaluate(prepared, row("y", OTHER))).containsExactly(row("y", OTHER, "result", OUTER));
		} finally {
			registry.remove(replacement);
			registry.remove(original);
		}
	}

