	private static Service authorityService(boolean silent, boolean fixedEndpoint) {
		TupleExpr body = new StatementPattern(Var.of("s"), Var.of("p", VF.createIRI("urn:frame:p"), false, true),
				Var.of("result"));
		Var endpoint = fixedEndpoint ? Var.of("endpoint", ENDPOINT, false, true) : Var.of("endpoint");
		return new Service(endpoint, body, "{ ?s <urn:frame:p> ?result }", Map.of(), null, silent);
	}

	private static FederatedService recordingService(Service service, AtomicReference<BindingSet> sent) {
		FederatedService remote = mock(FederatedService.class);
		when(remote.select(eq(service), anySet(), any(BindingSet.class), eq(service.getBaseURI())))
				.thenAnswer(invocation -> {
					BindingSet input = invocation.getArgument(2);
					sent.set(input);
					Value subject = input.getValue("s");
					return subject != null && !subject.equals(ENDPOINT) ? new EmptyIteration<BindingSet>()
							: new SingletonIteration<>(row("s", ENDPOINT, "result", OUTER));
				});
		return remote;
	}

