	@ParameterizedTest(name = "consumer first={0}")
	@ValueSource(booleans = { false, true })
	void tupleGroupLocalOutputWinsBeforeWithheldOptionalCompatibility(boolean reverse) {
		String producerUri = "urn:frame:tuple-local-producer";
		String consumerUri = "urn:frame:tuple-local-consumer";
		List<Value> observed = new ArrayList<>();
		TupleFunction producer = new TupleFunction() {
			@Override
			public String getURI() {
				return producerUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				return new SingletonIteration<>(List.of(OTHER));
			}
		};
		TupleFunction consumer = new TupleFunction() {
			@Override
			public String getURI() {
				return consumerUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add(args[0]);
				return new SingletonIteration<>(List.of(args[0]));
			}
		};
		TupleFunctionRegistry.getInstance().add(producer);
		TupleFunctionRegistry.getInstance().add(consumer);
		try {
			for (BindingSet input : List.of(row(), row("x", OTHER), row("x", OUTER))) {
				TupleFunctionCall first = new TupleFunctionCall();
				first.setURI(producerUri);
				first.addResultVar(Var.of("x"));
				TupleFunctionCall second = new TupleFunctionCall();
				second.setURI(consumerUri);
				second.addArg(Var.of("x"));
				second.addResultVar(Var.of("seen"));
				TupleExpr calls = reverse ? new Join(second, first) : new Join(first, second);
				Lateral group = new Lateral(new SingletonSet(), calls, Set.of("x", "seen"));
				TupleExpr optional = new LeftJoin(new SingletonSet(), group);
				DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
				List<BindingSet> rows = evaluate(strategy.precompile(optional), input);
				if (OUTER.equals(input.getValue("x"))) {
					List<BindingSet> gated = evaluate(strategy.precompile(
							new Filter(optional.clone(), new Bound(Var.of("seen")))), input);
					assertAll(
							() -> assertThat(rows).as("bare incompatible OPTIONAL retains its input")
									.containsExactly(input),
							() -> assertThat(gated).as("BOUND(seen) removes the unmatched row").isEmpty());
				} else {
					assertThat(rows).containsExactly(row("x", OTHER, "seen", OTHER));
				}
			}
			assertThat(observed).containsExactly(OTHER, OTHER, OTHER, OTHER);
		} finally {
			TupleFunctionRegistry.getInstance().remove(consumer);
			TupleFunctionRegistry.getInstance().remove(producer);
		}
	}

