	@Test
	void publicLeftJoinConstructorAppliesEntryCompatibilityBeforeMatch() {
		BindingSet caller = row("x", OUTER);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet newerEmpty = BindingFrameBindings.withSubstitutionDomain(caller, Set.of(), context);
		List<BindingSet> conflict = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null, caller, false);
		List<BindingSet> conflictGate = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null, caller, true);
		List<BindingSet> matched = constructorOptional(values(row("x", OUTER, "hit", OTHER)), null, caller, false);
		List<BindingSet> matchedCondition = constructorOptional(values(row("x", OUTER, "hit", OTHER)),
				new Bound(Var.of("hit")), caller, false);
		List<BindingSet> falseCondition = constructorOptional(values(row("x", OUTER, "hit", OTHER)),
				new ValueConstant(VF.createLiteral(false)), caller, false);
		BindingSetAssignment undef = values(row("hit", OTHER));
		undef.setBindingNames(Set.of("x", "hit"));
		List<BindingSet> undefRows = constructorOptional(undef, null, caller, false);
		List<BindingSet> unboundRows = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null, row(), false);
		List<BindingSet> disjointRows = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null,
				row("unrelated", OUTER), false);
		List<BindingSet> marked = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null, newerEmpty, false);
		List<BindingSet> markedGate = constructorOptional(values(row("x", OTHER, "hit", OTHER)), null, newerEmpty,
				true);
		assertAll(
				() -> assertThat(conflict).as("an incompatible candidate preserves the caller").containsExactly(caller),
				() -> assertThat(conflictGate).as("BOUND(hit) removes the unmatched caller").isEmpty(),
				() -> assertThat(matched).as("a compatible candidate matches")
						.containsExactly(row("x", OUTER, "hit", OTHER)),
				() -> assertThat(matchedCondition).as("the user condition sees the matched hit")
						.containsExactly(row("x", OUTER, "hit", OTHER)),
				() -> assertThat(falseCondition).as("a false user condition preserves the caller")
						.containsExactly(caller),
				() -> assertThat(undefRows).as("an unbound RHS x remains compatible")
						.containsExactly(row("x", OUTER, "hit", OTHER)),
				() -> assertThat(unboundRows).as("an unbound caller accepts the local row")
						.containsExactly(row("x", OTHER, "hit", OTHER)),
				() -> assertThat(disjointRows).as("a disjoint caller is retained with the local row")
						.containsExactly(row("unrelated", OUTER, "x", OTHER, "hit", OTHER)),
				() -> assertThat(marked).as("the empty invocation matches locally before later restoration").isEmpty(),
				() -> assertThat(markedGate).as("the gate cannot undo a later incompatible restoration").isEmpty());
	}

