	@ParameterizedTest(name = "OPTIONAL condition={0}")
	@ValueSource(strings = { "true", "false", "error", "volatile" })
	void publicOptionalMatchesOnlyCompatibleCandidatesBeforeItsCondition(String conditionKind) {
		String tupleUri = "urn:frame:optional-compatibility-mixed-tuple";
		String conditionUri = "urn:frame:optional-compatibility-condition";
		List<Value> arguments = new ArrayList<>();
		List<List<Value>> conditionArguments = new ArrayList<>();
		TupleFunction tuple = new TupleFunction() {
			@Override
			public String getURI() {
				return tupleUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				arguments.add(args[0]);
				List<List<Value>> candidates = List.of(List.of(ENDPOINT, OTHER), List.of(OUTER, OTHER),
						List.of(OUTER, OTHER));
				return new CloseableIteratorIteration<>(candidates.iterator());
			}
		};
		Function conditionFunction = new Function() {
			@Override
			public String getURI() {
				return conditionUri;
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.VOLATILE;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				conditionArguments.add(List.of(args));
				return factory.createLiteral(true);
			}
		};
		TupleFunctionRegistry.getInstance().add(tuple);
		FunctionRegistry.getInstance().add(conditionFunction);
		try {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(tupleUri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			call.addResultVar(Var.of("hit"));
			Lateral lateral = new Lateral(new SingletonSet(), call, Set.of("x"));
			ValueExpr condition = switch (conditionKind) {
			case "true" -> new ValueConstant(VF.createLiteral(true));
			case "false" -> new ValueConstant(VF.createLiteral(false));
			case "error" -> new MathExpr(new ValueConstant(OUTER), new ValueConstant(VF.createLiteral(1)),
					MathExpr.MathOp.PLUS);
			case "volatile" -> new FunctionCall(conditionUri, Var.of("x"), Var.of("hit"), Var.of("anchor"));
			default -> throw new AssertionError(conditionKind);
			};
			LeftJoin optional = new LeftJoin(values(row("anchor", OTHER), row("anchor", OTHER)), lateral, condition);
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
			List<BindingSet> actual = evaluate(strategy.precompile(optional), row("x", OUTER));
			BindingSet matched = row("anchor", OTHER, "x", OUTER, "hit", OTHER);
			BindingSet fallback = row("anchor", OTHER, "x", OUTER);
			List<BindingSet> expected = conditionKind.equals("true") || conditionKind.equals("volatile")
					? List.of(matched, matched, matched, matched)
					: List.of(fallback, fallback);
			assertAll(
					() -> assertThat(actual).as("exact compatible OPTIONAL bag")
							.containsExactlyInAnyOrderElementsOf(expected),
					() -> assertThat(arguments).as("actual tuple-function inputs").isNotEmpty().allMatch(OUTER::equals),
					() -> {
						if (conditionKind.equals("volatile")) {
							assertThat(conditionArguments).as("condition sees each compatible merged occurrence")
									.containsExactlyInAnyOrderElementsOf(List.of(List.of(OUTER, OTHER, OTHER),
											List.of(OUTER, OTHER, OTHER), List.of(OUTER, OTHER, OTHER),
											List.of(OUTER, OTHER, OTHER)));
						}
					});
		} finally {
			FunctionRegistry.getInstance().remove(conditionFunction);
			TupleFunctionRegistry.getInstance().remove(tuple);
		}
	}

