	@Test
	void framedDeferredArgumentDoesNotBecomeNestedOptionalLeftBinding() {
		String uri = "urn:frame:deferred-recipient-witness";
		List<Value> observed = new ArrayList<>();
		TupleFunction function = selfWitnessFunction(uri, observed, false);
		TupleFunctionRegistry.getInstance().add(function);
		try {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
			TupleExpr call = selfWitnessLateral(uri, new SingletonSet()).getRightArg();
			QueryEvaluationStep tuple = strategy.precompile(call, context);
			BindingFrameBindings.TupleParameterConsumer consumer = BindingFrameBindings.unframedCapability(tuple,
					BindingFrameBindings.TupleParameterConsumer.class);
			assertThat(consumer).isNotNull();
			BindingFrameBindings.TupleParameterGrant grant = consumer.tupleParameterGrant();
			BindingFrameBindings.TupleParameterGrant wrong = new BindingFrameBindings.TupleParameterGrant(Set.of("x"));
			BindingSet caller = row("x", OUTER);
			BindingSet withheld = BindingFrameBindings.without(caller, Set.of("x"), context);
			BindingSet olderProbe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), withheld,
					row("x", ENDPOINT), context);
			BindingSet deferred = BindingFrameBindings.withLateralDomain(olderProbe, Set.of(), Set.of("x"), olderProbe,
					Set.of("x"), Set.of("x"), List.of(grant), context);
			BindingSet youngerProbe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), deferred,
					row("x", ENDPOINT), context);
			BindingSet newerMarker = BindingFrameBindings.withSubstitutionDomain(deferred, Set.of(), context);
			BindingSet noValue = BindingFrameBindings.push(new BindingFrameBindings.Scope(), row(), row("x", ENDPOINT),
					context);
			BindingSet unbound = BindingFrameBindings.withLateralDomain(noValue, Set.of(), Set.of("x"), noValue,
					Set.of("x"), Set.of("x"), List.of(grant), context);
			LeftJoin inner = new LeftJoin(new SingletonSet(), values(row("x", OTHER, "hit", VF.createLiteral(true))));
			List<BindingSet> rows = evaluate(strategy.precompile(inner, context), deferred);
			List<BindingSet> tupleRows = evaluate(tuple, deferred);
			assertAll(
					() -> assertThat(deferred.getValue("x")).as("deferred argument is not a logical binding").isNull(),
					() -> assertThat(BindingFrameBindings.currentEntryWithheldInput(deferred, "x")).isNull(),
					() -> assertThat(grant.value(deferred, "x")).as("exact tuple recipient").isEqualTo(OUTER),
					() -> assertThat(wrong.value(deferred, "x")).as("wrong recipient").isNull(),
					() -> assertThat(BindingFrameBindings.probeValue(deferred, "x"))
							.as("older ordinary probe remains shadowed")
							.isNull(),
					() -> assertThat(BindingFrameBindings.probeValue(youngerProbe, "x")).isEqualTo(ENDPOINT),
					() -> assertThat(grant.value(youngerProbe, "x")).isEqualTo(OUTER),
					() -> assertThat(grant.value(newerMarker, "x")).as("new marker blocks old grant").isNull(),
					() -> assertThat(grant.value(unbound, "x")).isNull(),
					() -> assertThat(BindingFrameBindings.probeValue(unbound, "x"))
							.as("unbound recipient shadows older ordinary probe")
							.isNull(),
					() -> assertThat(BindingFrameBindings.substitutionDomain(deferred)).isEmpty(),
					() -> assertThat(tupleRows).as("the prepared tuple actually reads its argument")
							.containsExactly(row("x", OUTER, "hit", OTHER)),
					() -> assertThat(observed).containsExactly(OUTER),
					() -> assertThat(rows).as("the nested OPTIONAL matches its own local output")
							.containsExactly(row("x", OTHER, "hit", VF.createLiteral(true))),
					() -> assertThat(rows).singleElement()
							.satisfies(local -> assertThat(caller.isCompatible(local)).isFalse()));
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

