	private static TupleFunction selfWitnessFunction(String uri, List<Value> observed, boolean differentOutput) {
		return new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add(args[0]);
				if (ENDPOINT.equals(args[0])) {
					return new EmptyIteration<>();
				}
				return new SingletonIteration<>(List.of(differentOutput ? ENDPOINT : args[0], OTHER));
			}
		};
	}

	private static LeftJoin selfWitnessOptional(String uri, TupleExpr lateralLeft) {
		return new LeftJoin(new SingletonSet(), selfWitnessLateral(uri, lateralLeft));
	}

	private static Lateral selfWitnessLateral(String uri, TupleExpr lateralLeft) {
		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI(uri);
		call.addArg(Var.of("x"));
		call.addResultVar(Var.of("x"));
		call.addResultVar(Var.of("hit"));
		return new Lateral(lateralLeft, call, Set.of("x"));
	}

