	/** Characterizes the existing deterministic ready order for an unresolved two-call cycle. */
	@ParameterizedTest(name = "first call is F={0}")
	@ValueSource(booleans = { false, true })
	void tupleGroupCyclicInputOrderDiagnostic(boolean firstF) {
		String fUri = "urn:frame:cycle-f";
		String gUri = "urn:frame:cycle-g";
		Value seed = VF.createLiteral("seed");
		Value bad = VF.createLiteral("bad");
		Value good = VF.createLiteral("good");
		List<String> observed = new ArrayList<>();
		TupleFunction f = new TupleFunction() {
			@Override
			public String getURI() {
				return fUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add("F:" + args[0].stringValue());
				if (!good.equals(args[0])) {
					throw new ValueExprEvaluationException("cycle F requires good");
				}
				return new SingletonIteration<>(List.of(seed, VF.createLiteral("witness")));
			}
		};
		TupleFunction g = new TupleFunction() {
			@Override
			public String getURI() {
				return gUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add("G:" + args[0].stringValue());
				return new SingletonIteration<>(List.of(good));
			}
		};
		TupleFunctionRegistry.getInstance().add(f);
		TupleFunctionRegistry.getInstance().add(g);
		try {
			TupleFunctionCall fCall = new TupleFunctionCall();
			fCall.setURI(fUri);
			fCall.addArg(Var.of("y"));
			fCall.addResultVar(Var.of("x"));
			fCall.addResultVar(Var.of("witness"));
			TupleFunctionCall gCall = new TupleFunctionCall();
			gCall.setURI(gUri);
			gCall.addArg(Var.of("x"));
			gCall.addResultVar(Var.of("y"));
			TupleExpr calls = firstF ? new Join(fCall, gCall) : new Join(gCall, fCall);
			Lateral group = new Lateral(new SingletonSet(), calls, Set.of("x", "y", "witness"));
			Projection projected = new Projection(group,
					new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("witness")), true);
			TupleExpr optional = new LeftJoin(new SingletonSet(), projected);
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
			assertThat(evaluate(strategy.precompile(optional), row("x", seed, "y", bad)))
					.containsExactly(row("x", seed, "y", bad));
			assertThat(observed).containsExactly(firstF ? "F:bad" : "G:seed");
		} finally {
			TupleFunctionRegistry.getInstance().remove(g);
			TupleFunctionRegistry.getInstance().remove(f);
		}
	}

	@ParameterizedTest(name = "outer output matches local={0}")
	@ValueSource(booleans = { false, true })
	void cyclicTupleCallsDeferUnrelatedLocalOutput(boolean matches) {
		String fUri = "urn:frame:cycle-output-f";
		String gUri = "urn:frame:cycle-output-g";
		String hUri = "urn:frame:cycle-output-h";
		Value seed = VF.createLiteral("seed");
		Value good = VF.createLiteral("good");
		Value local = VF.createLiteral("local");
		Value outer = matches ? local : VF.createLiteral("outer");
		List<String> observed = new ArrayList<>();
		TupleFunction f = new TupleFunction() {
			@Override
			public String getURI() {
				return fUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add("F:" + args[0].stringValue());
				return new SingletonIteration<>(List.of(seed, local));
			}
		};
		TupleFunction g = new TupleFunction() {
			@Override
			public String getURI() {
				return gUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add("G:" + args[0].stringValue());
				return new SingletonIteration<>(List.of(good));
			}
		};
		TupleFunction h = new TupleFunction() {
			@Override
			public String getURI() {
				return hUri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add("H:" + args[0].stringValue());
				return new SingletonIteration<>(List.of(args[0]));
			}
		};
		TupleFunctionRegistry.getInstance().add(f);
		TupleFunctionRegistry.getInstance().add(g);
		TupleFunctionRegistry.getInstance().add(h);
		try {
			TupleFunctionCall fCall = new TupleFunctionCall();
			fCall.setURI(fUri);
			fCall.addArg(Var.of("y"));
			fCall.addResultVar(Var.of("x"));
			fCall.addResultVar(Var.of("z"));
			TupleFunctionCall gCall = new TupleFunctionCall();
			gCall.setURI(gUri);
			gCall.addArg(Var.of("x"));
			gCall.addResultVar(Var.of("y"));
			TupleFunctionCall hCall = new TupleFunctionCall();
			hCall.setURI(hUri);
			hCall.addArg(Var.of("z"));
			hCall.addResultVar(Var.of("seen"));
			Lateral group = new Lateral(new SingletonSet(), new Join(new Join(fCall, gCall), hCall),
					Set.of("x", "y", "z"));
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
			QueryEvaluationStep step = strategy.precompile(new LeftJoin(new SingletonSet(), group));
			BindingSet caller = row("x", seed, "y", good, "z", outer);
			List<BindingSet> actual = evaluate(step, caller);
			List<String> callerArguments = List.copyOf(observed);
			observed.clear();
			List<BindingSet> marked = evaluate(step, emptySubstitutionDomain(caller));
			List<String> markedArguments = List.copyOf(observed);
			if (matches) {
				assertThat(actual).containsExactly(row("x", seed, "y", good, "z", local, "seen", local));
				assertThat(marked).containsExactly(row("x", seed, "y", good, "z", local, "seen", local));
			} else {
				assertThat(actual).containsExactly(caller);
				assertThat(marked).isEmpty();
			}
			assertThat(callerArguments).containsExactly("F:good", "G:seed", "H:local");
			assertThat(markedArguments).containsExactly("F:good", "G:seed", "H:local");
		} finally {
			TupleFunctionRegistry.getInstance().remove(h);
			TupleFunctionRegistry.getInstance().remove(g);
			TupleFunctionRegistry.getInstance().remove(f);
		}
	}

