	@Test
	void newLateralReceivesCurrentWithheldInputAfterAnOlderEmptyInvocation() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet input = currentWithheldAfterEmptyInvocation(context);
		Extension right = new Extension(new SingletonSet(), new ExtensionElem(Var.of("x"), "copy"));
		Lateral lateral = new Lateral(new SingletonSet(), right, Set.of("x"));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		QueryEvaluationStep rightStep = strategy.precompile(right, context);
		QueryEvaluationStep suppliedStep = new LateralQueryEvaluationStep(
				bindings -> new SingletonIteration<>(bindings), rightStep, lateral);
		QueryEvaluationStep standardStep = strategy.precompile(lateral, context);
		List<BindingSet> suppliedRows = evaluate(suppliedStep, input);
		List<BindingSet> standardRows = evaluate(standardStep, input);
		assertAll(
				() -> assertThat(suppliedRows).as("supplied prepared steps")
						.containsExactly(row("graph", ENDPOINT, "copy", OUTER)),
				() -> assertThat(standardRows).as("standard precompile")
						.containsExactly(row("graph", ENDPOINT, "copy", OUTER)),
				() -> assertThat(GraphFrameBindings.isSupplied(suppliedRows.getFirst(), "graph")).isTrue(),
				() -> assertThat(GraphFrameBindings.isSupplied(standardRows.getFirst(), "graph")).isTrue());
	}

	@Test
	void newLateralCannotRecoverAValueHiddenBelowANewerInvocation() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet older = BindingFrameBindings.withSubstitutionDomain(row("x", OUTER), Set.of("x"), context);
		BindingSet oldWithheld = BindingFrameBindings.without(older, Set.of("x"), context);
		BindingSet newerEmpty = BindingFrameBindings.withSubstitutionDomain(oldWithheld, Set.of(), context);
		BindingSet newerUnbound = BindingFrameBindings.withLateralDomain(oldWithheld, Set.of("x"), Set.of("x"),
				context);
		Extension right = new Extension(new SingletonSet(), new ExtensionElem(Var.of("x"), "copy"));
		Lateral lateral = new Lateral(new SingletonSet(), right, Set.of("x"));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		QueryEvaluationStep standardStep = strategy.precompile(lateral, context);
		QueryEvaluationStep suppliedStep = new LateralQueryEvaluationStep(
				bindings -> new SingletonIteration<>(bindings), strategy.precompile(right, context), lateral);
		assertAll(
				() -> assertThat(evaluate(standardStep, newerEmpty)).as("standard empty domain").containsExactly(row()),
				() -> assertThat(evaluate(standardStep, newerUnbound)).as("standard declared UNDEF")
						.containsExactly(row()),
				() -> assertThat(evaluate(suppliedStep, newerEmpty)).as("supplied empty domain").containsExactly(row()),
				() -> assertThat(evaluate(suppliedStep, newerUnbound)).as("supplied declared UNDEF")
						.containsExactly(row()));
	}

	private static BindingSet currentWithheldAfterEmptyInvocation(QueryEvaluationContext context) {
		BindingSet older = BindingFrameBindings.withSubstitutionDomain(EmptyBindingSet.getInstance(), Set.of(),
				context);
		MutableBindingSet local = BindingFrameBindings.preserve(older, context.createBindingSet(older));
		local = GraphFrameBindings.supply(local, "graph", ENDPOINT);
		local.setBinding("x", OUTER);
		return BindingFrameBindings.without(local, Set.of("x"), context);
	}

