	private static void assertService(boolean fail, boolean ask) {
		TupleExpr body = new StatementPattern(Var.of("s"), Var.of("p", VF.createIRI("urn:frame:p"), false, true),
				ask ? Var.of("o", VF.createLiteral("object"), false, true) : Var.of("result"));
		Service service = new Service(Var.of("service", REMOTE, false, true), body,
				ask ? "{ ?s <urn:frame:p> \"object\" }" : "{ ?s <urn:frame:p> ?result }", Map.of(), null, fail);
		FederatedService remote = mock(FederatedService.class);
		AtomicReference<BindingSet> incoming = new AtomicReference<>();
		if (ask) {
			when(remote.ask(eq(service), any(BindingSet.class), eq(service.getBaseURI()))).thenAnswer(invocation -> {
				incoming.set(invocation.getArgument(1));
				return true;
			});
		} else {
			when(remote.select(eq(service), anySet(), any(BindingSet.class), eq(service.getBaseURI())))
					.thenAnswer(invocation -> {
						incoming.set(invocation.getArgument(2));
						if (fail) {
							throw new QueryEvaluationException("expected SERVICE failure");
						}
						return new SingletonIteration<>(row("result", VF.createLiteral("remote")));
					});
		}
		FederatedServiceResolver resolver = mock(FederatedServiceResolver.class);
		when(resolver.getService(REMOTE.stringValue())).thenReturn(remote);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), resolver);
		TupleExpr rhs = new Extension(service, new ExtensionElem(Var.of("s"), "witnessed"),
				new ExtensionElem(Var.of("outer"), "leaked"));
		List<BindingSet> rows = evaluate(strategy, optional(rhs));
		MapBindingSet expected = row("s", ENDPOINT, "outer", OUTER);
		if (!fail) {
			expected.addBinding("witnessed", ENDPOINT);
			if (!ask) {
				expected.addBinding("result", VF.createLiteral("remote"));
			}
		}
		assertThat(rows).containsExactly(expected);
		assertThat(incoming.get()).isNotNull();
		assertThat(incoming.get().getValue("s")).isEqualTo(ENDPOINT);
		assertThat(incoming.get().hasBinding("outer")).isFalse();
	}

